'use strict';
let strategyCountry='MEX',strategyChild='mat',strategyHorizon='now',strategyScenario='fast';
function renderFamilyStrategy(){
 const f=DATA.family_strategy,root=document.querySelector('#strategy-content');if(!f||!root)return;
 const child=f.children[strategyChild],base=f.bases.find(b=>b.iso===strategyCountry),h=f.horizons.find(x=>x.id===strategyHorizon),scenario=(f.scenarios||[]).find(x=>x.id===strategyScenario);
 const links=xs=>xs.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a>`).join('');
 root.innerHTML=`<div class="strategy-intro"><div><p class="section-kicker">СЕМЕЙНОЕ РЕШЕНИЕ · ${esc(f.checked)}</p><h3>Одна база.<br>Два собственных <em>маршрута.</em></h3><p>${esc(f.conclusion)}</p><span class="strategy-editorial">Рекомендация по найденным досье · места ещё не подтверждены</span></div><div class="strategy-blueprint" aria-label="Развитие через практику, команду и собственный продукт"><div class="strategy-orbit"></div><div class="strategy-node sn-one"><span>01</span><b>Изучать</b><small>Математика · код</small></div><div class="strategy-node sn-two"><span>02</span><b>Создавать</b><small>Робот · прототип</small></div><div class="strategy-node sn-three"><span>03</span><b>Проверять</b><small>Команда · пользователь</small></div><div class="strategy-core" aria-hidden="true">✦</div></div></div>
 <div class="strategy-thesis"><b>Мой критерий переезда</b><p>${esc(f.decision)}</p><p>${esc(f.rationale)}</p></div>
 ${scenario?`<div class="strategy-heading"><h3>Три сценария для сравнения</h3><p>${esc(f.confidence)}</p></div><div class="strategy-scenario-tabs" role="group" aria-label="Сценарий постоянной базы">${f.scenarios.map(x=>`<button data-strategy-scenario="${esc(x.id)}" aria-pressed="${x.id===strategyScenario}" class="${x.id===strategyScenario?'active':''}">${esc(x.name)}</button>`).join('')}</div><article class="strategy-scenario" data-selected-scenario="${esc(scenario.id)}"><div><p class="section-kicker">СЦЕНАРИЙ · ${esc(scenario.iso)}</p><h4>${esc(scenario.title)}</h4><p>${esc(scenario.detail)}</p><p class="strategy-child-note"><b>${esc(child.name)}:</b> ${esc(scenario[strategyChild])}</p></div><ol>${scenario.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></article>`:''}
 <div class="strategy-child-switch" role="group" aria-label="Маршрут ребёнка">${Object.entries(f.children).map(([id,c])=>`<button data-strategy-child="${id}" aria-pressed="${id===strategyChild}" class="${id===strategyChild?'active':''}">${esc(c.name)} <small>${esc(c.birth_year)}</small></button>`).join('')}<span>Одна семейная база, своя роль у каждого.</span></div>
 <section class="strategy-child-route" aria-label="Рекомендация ребёнку"><p class="section-kicker">${esc(child.name.toUpperCase())} · СЕЙЧАС</p><h4>${esc(child.default)}</h4><p>${esc(child.detail)}</p><ul>${child.current.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p class="strategy-proof"><b>Через сезон:</b> ${esc(child.proof)}</p><div class="strategy-sources">${links(child.sources)}</div></section>
 <div class="strategy-heading"><h3>Где строить постоянную среду</h3><p>Роль каждой базы — наша оценка. Факты школы и условия входа показаны отдельно.</p></div>
 <div class="strategy-base-grid" role="group" aria-label="Выбор семейной базы">${f.bases.map((b,i)=>`<button data-strategy-country="${esc(b.iso)}" aria-pressed="${b.iso===strategyCountry}" class="strategy-base ${b.iso===strategyCountry?'active':''}"><span class="strategy-base-code">${esc(b.iso)}</span><b>${esc(b.name.split(' · ')[0])}</b><small>${esc(b.verdict)}</small></button>`).join('')}</div>
 <article class="strategy-country-detail" data-selected-base="${esc(base.iso)}"><div><p class="section-kicker">${esc(base.role.toUpperCase())}</p><h3>${esc(base.name)}</h3><p class="strategy-opinion">${esc(base.recommendation)}</p><div class="strategy-verified"><b>Что описано официально</b><p>${esc(base.verified)}</p></div><p class="strategy-child-note"><b>${esc(child.name)}:</b> ${esc(base.child_notes[strategyChild])}</p></div><div class="strategy-gates"><h4>Что решит выбор</h4><ul>${base.gates.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p><b>Следующий шаг:</b> ${esc(base.next)}</p><div class="strategy-school-links">${base.school_ids.map(id=>`<button class="button secondary" data-school-open="${id}">${esc(DATA.schools.find(x=>x.id===id).name)} · досье ↗</button>`).join('')}</div></div><div class="strategy-sources">${links(base.sources)}</div></article>
 ${f.cost_comparison?`<div class="strategy-heading"><h3>Обучение обоих · ${esc(f.cost_comparison.school_year)}</h3><p>${esc(f.cost_comparison.note)}</p></div><div class="strategy-cost-grid">${f.cost_comparison.schools.map(x=>`<article class="strategy-cost" data-cost-school="${esc(x.school_id)}"><p class="section-kicker">${esc(x.iso)} · ДВА РЕБЁНКА</p><h4>${esc(x.name)}</h4><dl><dt>Ежегодное обучение / указанные ежегодные сборы</dt><dd>${esc(x.annual)}</dd><dt>Разовые взносы / заявки</dt><dd>${esc(x.entry)}</dd><dt>Первый год / полное обязательство</dt><dd class="strategy-cost-total">${esc(x.first)}</dd></dl><details><summary>Как рассчитано и что не включено</summary><p>${esc(x.formula)}</p></details><div class="strategy-sources"><a href="${esc(x.url)}" target="_blank" rel="noopener">Тариф школы · 2026–27 ↗</a><button class="button secondary" data-school-open="${esc(x.school_id)}">Досье школы ↗</button></div></article>`).join('')}</div>`:''}
 <div class="strategy-heading"><h3>Инженер. Разработчик. Создатель продукта.</h3><p>В младшем возрасте эти направления можно сочетать. Специализацию выбирать по собственному интересу и работе.</p></div>
 <div class="strategy-track-grid">${f.tracks.map((t,i)=>`<article class="strategy-track"><span>0${i+1}</span><h4>${esc(t.name)}</h4><p>${esc(t.detail)}</p><p class="strategy-child-note">${esc(t[strategyChild])}</p><p><b>Признак результата:</b> ${esc(t.proof)}</p></article>`).join('')}</div>
 <div class="strategy-heading"><h3>Как путь меняется со временем</h3><p>Будущие годы — план развития. Допуск перепроверяется по правилам каждого сезона.</p></div>
 <div class="strategy-horizon-tabs" role="group" aria-label="Горизонт развития">${f.horizons.map(x=>`<button data-strategy-horizon="${esc(x.id)}" aria-pressed="${x.id===strategyHorizon}" class="${x.id===strategyHorizon?'active':''}">${esc(x.name)}</button>`).join('')}</div>
 <article class="strategy-horizon" data-selected-horizon="${esc(h.id)}"><h4>${esc(h.name)}</h4><p class="strategy-child-note"><b>${esc(child.name)}:</b> ${esc(h[strategyChild])}</p><p>${esc(h.base)}</p><p class="strategy-proof">${esc(h.decision)}</p><div class="strategy-sources">${links(h.sources||[])}</div></article>
 <div class="strategy-heading"><h3>Следующие 90 дней</h3><p>От сравнительной проверки к постоянной практике.</p></div><ol class="strategy-actions">${f.actions.map(a=>`<li><span>${esc(a.period)}</span><div><h4>${esc(a.title)}</h4><p>${esc(a.detail)}</p></div></li>`).join('')}</ol>
 <details class="strategy-method"><summary>По каким признакам сравнивать школу и команду</summary><ul>${f.selection.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>
 <details class="strategy-method"><summary>Исходные условия семьи и что ещё неизвестно</summary><ul>${f.assumptions.concat(f.gaps).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>
 <div class="strategy-downloads"><a class="button primary" href="downloads/STEM_family_strategy.md" download>Полный маршрут · текст ↓</a><a class="button secondary" href="downloads/STEM_family_strategy.json" download>Стратегия и источники · JSON ↓</a><button class="button secondary" data-view="schools">Сравнить все школы ↗</button><button class="button secondary" data-view="leagues">Правила лиг ↗</button></div>`;
}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 let selector;
 if(b.dataset.strategyScenario){strategyScenario=b.dataset.strategyScenario;strategyCountry=DATA.family_strategy.scenarios.find(x=>x.id===strategyScenario).iso;selector=`[data-strategy-scenario="${strategyScenario}"]`}
 if(b.dataset.strategyChild){strategyChild=b.dataset.strategyChild;selector=`[data-strategy-child="${strategyChild}"]`}
 if(b.dataset.strategyCountry){strategyCountry=b.dataset.strategyCountry;selector=`[data-strategy-country="${strategyCountry}"]`}
 if(b.dataset.strategyHorizon){strategyHorizon=b.dataset.strategyHorizon;selector=`[data-strategy-horizon="${strategyHorizon}"]`}
 if(selector){renderFamilyStrategy();document.querySelector(selector).focus({preventScroll:true})}
});
